enum Paiement {
    EnAttente,
    Valide { reference: String },
    Refuse(String),
}

fn statut(p: &Paiement) -> String {
    match p {
        Paiement::EnAttente => "attente".into(),
        Paiement::Valide { reference: r } => r.clone(),
        Paiement::Refuse(m) => format!("refus : {m}"),
    }
}
let p = Paiement::Refuse("carte".into());
println!("{}", statut(&p));

