use std::fmt;

struct Euros(u32);

impl fmt::Display for Euros {
    fn fmt(&self, f: &mut fmt::Formatter)
        -> fmt::Result {
        let (e, c) = (self.0 / 100, self.0 % 100);
        write!(f, "{e},{c:02} €")
    }
}

println!("{}", Euros(1905));

fn plus_grand<T>(a: T, b: T) -> T {
