}

enum Commande { Panier, Payee(u32), Expediee(String) }

fn suivant(c: Commande) -> Commande {
    use Commande::*;
    match c {
        Panier => Payee(4990),
        Payee(_) => Expediee("FR123".into()),
        e => e,
    }
}

let c = suivant(suivant(Commande::Panier));
if let Commande::Expediee(n) = c {
    println!("{n}");
}

